import{_ as e,o as a,c as o,aj as n}from"./chunks/framework.BwH0p-pt.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/introduction/index.md","filePath":"3.0/introduction/index.md","lastUpdated":1785836850000}'),r={name:"3.0/introduction/index.md"};function s(i,t,c,p,d,l){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a> is an open-source Product Information Management (PIM) system built on the <strong>Laravel 13</strong> framework and requires <strong>PHP 8.4</strong>. It runs on MySQL 8.0.32+ or PostgreSQL 16, with optional Elasticsearch 8.19 for faster search. It helps businesses organize, manage, and enrich their product information in one central repository.</p><div class="tip custom-block"><p class="custom-block-title">Current Version — v3.0.0</p><p>This guide covers UnoPim <strong>v3.0.0</strong>, released 31 July 2026. v3.0.0 introduces Digital Product Passports, configurable product associations, product variants with inheritance, a full Measurements module, product-grid filters with saved views, a modernized admin with dark mode and no-reload navigation, Microsoft SSO, multiple webhooks, and a new System Settings hub. See <strong><a href="./../releases/">What&#39;s New</a></strong> for the full list.</p></div><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><p><strong>1) Centralized Product Management-</strong> Manage all your product data in one place with support for Simple and Configurable product types.</p><p><strong>2) Data Enrichment-</strong> Enhance your product information with detailed attributes, including support for 12 data types and swatch types for visual attribute options.</p><p><strong>3) Category Management-</strong> Organize products into categories for easier navigation, with customizable category fields.</p><p><strong>4) Digital Product Passports-</strong> Create and publish Digital Product Passports that share regulation-ready product information on public, QR-code-friendly pages. Templates, version history, and ESPR and EU Battery Regulation presets help you meet compliance requirements. See <strong><a href="./../passport/">Product Passports</a></strong>.</p><p><strong>5) Configurable Product Associations-</strong> Define your own association types with custom labels and link fields, instead of being limited to fixed relations. Link products the way your business works — bundles, spare parts, accessories, and more. See <strong><a href="./../associations/">Associations</a></strong>.</p><p><strong>6) Product Variants with Inheritance-</strong> Build variant structures with configurable axes where variants automatically inherit shared values from their parent. Enrich common data once and let every variant stay in sync. See <strong><a href="./../products/variants.html">Product Variants</a></strong>.</p><p><strong>7) Measurements-</strong> Manage measurement families, units, and automatic conversions so product dimensions and weights stay consistent across your catalog. See <strong><a href="./../measurements/">Measurements</a></strong>.</p><p><strong>8) Filters &amp; Saved Views-</strong> Filter the product grid by categories, completeness, dates, properties, and attribute values, then save your favorite column and filter combinations as reusable views. See <strong><a href="./../products/filters-and-views.html">Filters &amp; Saved Views</a></strong>.</p><p><strong>9) Modernized Admin Experience-</strong> Work in a refreshed admin panel with a dark theme, no-reload page navigation, and a global Save bar that tracks unsaved changes. See <strong><a href="./admin-essentials.html">Admin Essentials</a></strong>.</p><p><strong>10) User Management-</strong> Control user access and permissions with role-based access control.</p><p><strong>11) Microsoft SSO-</strong> Let your team sign in to the admin panel with their Microsoft work accounts for simpler, more secure access. See <strong><a href="./../configuration/microsoft-sso.html">Microsoft SSO</a></strong>.</p><p><strong>12) API Integration-</strong> Seamlessly integrate with other systems via RESTful APIs with OAuth 2.0 authentication.</p><p><strong>13) Localization-</strong> Support for multiple languages and locales with automatic AI-powered translation.</p><p><strong>14) Import/Export Functionality-</strong> Easily import and export product data using CSV, XLS, and XLSX formats, with drag-and-drop file upload, real-time job tracking, and pause/resume/cancel controls.</p><p><strong>15) Magic AI for Product Content Generation-</strong> Automatically generate engaging product content using advanced LLM technology with support for 10+ AI providers including OpenAI, Gemini, Anthropic, Ollama, and Groq.</p><p><strong>16) Multi-Channel Support-</strong> Manage and distribute your product data across multiple sales channels from a single platform.</p><p><strong>17) AI Agent Chat-</strong> Interact with your PIM using natural language through the AI Agent Chat interface with 30+ built-in PIM tools for product management, data quality, and bulk operations.</p><p><strong>18) Product Completeness-</strong> Monitor data quality with product completeness scoring that tracks how much required information has been filled in per channel and locale.</p><p><strong>19) Notifications-</strong> Stay informed with in-app and email notifications for import/export jobs, product changes, and system events.</p><p><strong>20) Multiple Webhooks-</strong> Set up as many webhooks as you need, each with its own URL and event subscriptions, secure signed delivery, and per-webhook delivery logs. See <strong><a href="./../configuration/webhooks.html">Webhooks</a></strong>.</p><p><strong>21) System Settings Hub-</strong> Manage appearance, email, sign-in options, measurements, publications, and Product Passport configuration from one searchable settings area. See <strong><a href="./../configuration/system-settings.html">System Settings</a></strong>.</p><p><strong>22) Enhanced Dashboard-</strong> Get a comprehensive overview of your catalog with widgets for product statistics, activity charts, completeness scores, channel readiness, and recent operations.</p><p><strong>23) Product Bulk Edit-</strong> Edit multiple products at once by selecting them from the datagrid and applying bulk changes to shared attributes.</p><p><strong>24) PostgreSQL Support-</strong> Full support for PostgreSQL databases in addition to MySQL for improved cross-database compatibility.</p><p><strong>25) Production-Ready Docker Setup-</strong> Spin up the full stack with one command using the official Docker Hub images. Multi-container setup with Nginx + PHP-FPM (Apache fallback available), Redis, Elasticsearch, and Mailpit.</p>',29)])])}const h=e(r,[["render",s]]);export{g as __pageData,h as default};
